mapper.select:
SELECT 'ORD-' || o.order_id AS orderId, o.account_id AS accountId, o.ticker AS symbol, o.side AS side, CAST(o.quantity AS BIGINT) AS quantity, o.price AS price, o.order_type AS orderType, CASE WHEN o.status = 'FILLED' THEN o.executed_price ELSE NULL END AS executedPrice, o.status AS status, o.idempotency_key AS idempotencyKey, o.rejection_reason AS rejectionReason, o.received_at AS createdOn FROM orders o WHERE o.account_id = #{accountId}
AND o.status = #{status}
AND o.received_at >= #{from}
AND o.received_at <= #{to}
ORDER BY o.received_at DESC, o.order_id DESC
